BEGIN TRANSACTION;
CREATE TABLE audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        project_code TEXT,
        step_name TEXT,
        message TEXT,
        status TEXT,
        timestamp TEXT
    );
CREATE TABLE cost_sheet_labor_phases (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        project_code TEXT,
        phase_code TEXT,
        phase_name TEXT,
        applicability TEXT,
        hours REAL,
        czk_per_hour REAL,
        budget_czk REAL
    );
CREATE TABLE cost_sheet_summary (
        project_code TEXT PRIMARY KEY,
        revision TEXT,
        approval_status TEXT,
        bac_czk REAL,
        labor_budget_czk REAL,
        equipment_budget_czk REAL,
        subcontract_budget_czk REAL,
        travel_budget_czk REAL,
        transport_budget_czk REAL,
        other_budget_czk REAL,
        contingency_budget_czk REAL,
        labor_hours REAL
    );
CREATE TABLE era_db_info (
        project_code TEXT PRIMARY KEY,
        project_name TEXT,
        project_manager TEXT,
        customer TEXT,
        project_type_1 TEXT,
        project_type_2 TEXT,
        planned_start_date TEXT,
        planned_completion_date TEXT,
        status_date TEXT,
        project_status TEXT,
        record_status TEXT,
        revision TEXT,
        hardware_planned REAL,
        subcontracting_planned REAL,
        travel_planned REAL,
        transport_planned REAL,
        labor_cost_planned REAL,
        other_costs_planned REAL,
        planned_contingency REAL,
        planned_warranty REAL,
        planned_commission REAL,
        planned_forex_adjustment REAL,
        total_planned REAL,
        hardware_actual REAL,
        subcontracting_actual REAL,
        travel_actual REAL,
        transport_actual REAL,
        labor_cost_actual REAL,
        other_costs_actual REAL,
        total_actual REAL,
        planned_hours REAL,
        actual_hours REAL,
        contract_value REAL,
        invoiced_amount REAL,
        invoice_status TEXT,
        overhead REAL,
        total_including_overhead REAL,
        remaining_to_invoice REAL,
        progress REAL,
        cost_center TEXT,
        contract_type TEXT,
        customer_reference TEXT,
        purchase_order_reference TEXT
    );
CREATE TABLE era_db_phase_hours (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        project_code TEXT,
        info_revision TEXT,
        status_date TEXT,
        phase_code TEXT,
        applicability TEXT,
        actual_hours REAL,
        provenance TEXT,
        scenario_revision TEXT
    );
CREATE TABLE evm_calculated_metrics (
        project_code TEXT PRIMARY KEY,
        bac_labor_hours REAL,
        bac_labor_czk REAL,
        ac_labor_czk REAL,
        pv_labor_czk REAL,
        ev_labor_czk REAL,
        labor_cpi REAL,
        labor_spi REAL,
        labor_cv REAL,
        labor_sv REAL,
        labor_etc_czk REAL,
        labor_eac_czk REAL,
        whole_project_bac REAL,
        whole_project_ac REAL,
        contract_value REAL,
        is_whole_project_evm_blocked INTEGER,
        blocking_reasons TEXT
    );
CREATE TABLE hitl_review_queue (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        project_code TEXT,
        category TEXT,
        field_name TEXT,
        source_a_label TEXT,
        source_a_value TEXT,
        source_b_label TEXT,
        source_b_value TEXT,
        discrepancy_delta TEXT,
        epistemic_tier TEXT,
        confidence_score REAL,
        reasoning TEXT,
        recommendation TEXT,
        status TEXT DEFAULT 'FLAGGED_FOR_MANUAL_REVIEW',
        reviewer_decision TEXT,
        reviewer_notes TEXT,
        created_at TEXT
    );
CREATE TABLE project_plan_phases (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        project_code TEXT,
        revision TEXT,
        phase_code TEXT,
        phase_name TEXT,
        start_date TEXT,
        finish_date TEXT,
        hours REAL,
        labor_czk REAL,
        plan_pct REAL,
        earned_pct REAL,
        applies TEXT
    );
CREATE TABLE project_plan_subtasks (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        project_code TEXT,
        task_id TEXT,
        parent_phase TEXT,
        subtask_name TEXT,
        start_date TEXT,
        finish_date TEXT,
        hours REAL,
        earned_pct REAL
    );
DELETE FROM "sqlite_sequence";
COMMIT;
